import { createRequire } from 'module'
import path, { dirname, join } from 'path'
import { fileURLToPath } from 'url'

const require = createRequire(import.meta.url)
const here = dirname(fileURLToPath(import.meta.url))

export default {
  stories: [
    '../stories/*.stories.tsx',
    // One story per docs example, generated by scripts/generate-stories.mjs.
    '../stories/generated/*.stories.tsx',
    '../../saas-ui-react/src/**/*.stories.tsx',
  ],

  addons: [
    getAbsolutePath("@storybook/addon-a11y"),
    getAbsolutePath("@storybook/addon-themes"),
    getAbsolutePath("@storybook/addon-docs")
  ],

  features: {
    buildStoriesJson: true,
  },

  staticDirs: ['./static'],

  typescript: {
    reactDocgen: false,
  },

  // refs: (config, { configType }) => {
  //   const refs = {
  //     '@chakra-ui/react': {
  //       disable: true, // Make sure Chakra gets loaded last
  //     },
  //     chakra: {
  //       title: 'Chakra UI',
  //       url: 'https://storybook.chakra-ui.com',
  //     },
  //   }
  //   if (configType === 'DEVELOPMENT') {
  //     return {
  //       '@saas-ui/pro': {
  //         title: 'Saas UI Pro',
  //         url: 'http://localhost:6007',
  //       },
  //       ...refs,
  //     }
  //   }
  //   return {
  //     '@saas-ui/pro': {
  //       title: 'Saas UI Pro',
  //       url: 'https://storybook.saas-ui.pro',
  //     },
  //     ...refs,
  //   }
  // },

  viteFinal(config) {
    config.resolve ??= {}
    config.resolve.alias = {
      ...(Array.isArray(config.resolve.alias) ? {} : config.resolve.alias),
      compositions: path.resolve(here, '../../../apps/compositions/src'),
    }
    // Resolve workspace packages to source, like the website does.
    config.resolve.conditions = [
      'sui',
      ...(config.resolve.conditions ?? [
        'module',
        'browser',
        'development|production',
      ]),
    ]
    return config
  },

  framework: {
    name: getAbsolutePath("@storybook/react-vite"),
  }
};

function getAbsolutePath(value) {
  return dirname(require.resolve(join(value, 'package.json')))
}
